useLayoutEffect(() => {
  if (clipStart === undefined || clipDuration === undefined) {
    return;
  }
  const clipEnd = clipStart + clipDuration;
  const onClip = range && rangeOnClip ? range : null;
  setStartText(rangeInputText(onClip ? Math.max(onClip.start, clipStart) : clipStart));
